"""Real Hohenheim charge/release, passive bursts, tracking/retarget input and Ahab eight-radius orders."""
import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
art=Path(__file__).resolve().parents[1]/'artifacts';art.mkdir(exist_ok=True)
with sync_playwright() as pw:
    b=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),headless=True,args=['--no-sandbox'])
    page=b.new_page(viewport={'width':1440,'height':900});errors=[]
    page.on('pageerror',lambda e:errors.append(str(e)))
    page.goto(os.environ.get('MOBA_TEST_URL','http://127.0.0.1:5180')+'/?debug=1',wait_until='networkidle')
    expect(page.locator('.build-tag')).to_contain_text('0.24.0')
    page.click('#training-open');page.get_by_role('button',name='호엔하임 선택',exact=True).click();page.click('#start')
    def fixture():
        page.evaluate('''() => {const g=__moba.game,p=g.player;for(const f of ['aiChampion','aiMinion','aiNeutral','aiStructure'])g[f]=()=>{};g.map={bounds:g.bounds,walls:[]};Object.assign(p,{x:40,y:20,alive:true,hp:p.maxHp,ammo:0,qCd:0,rCd:0,attackCd:0,invulnerableUntil:0,ccImmuneUntil:0,untargetableUntil:0,channelUntil:0,state:{},status:{},buffs:{},lastAttackAt:100,lastDamageAt:100});if(p.key==='ahab'){p.state.order='cover';g.addBuff(p,'ahabOrder',Infinity,{copy:false});}g.units=[p];g.events=[];g.pending=[];g.zones=[];g.projectiles=[];g.effects=[];g.minionQueue=[];g.practice.lineStopped=true;const t=g.makeChampion('faust',1,9);Object.assign(t,{x:44,y:20,maxHp:100000,hp:100000,lastAttackAt:100,lastDamageAt:100});window.__target=t;window.__hits=[];if(!window.__deal){window.__deal=g.deal.bind(g);g.deal=(a,b,n,o)=>{if(a===g.player&&b===window.__target)window.__hits.push({n,at:g.time,serial:a.attackSerial});return window.__deal(a,b,n,o);};}}''')
    def aim(x,y):
        pos=page.evaluate('([x,y])=>{const r=__moba.renderer;r.resize();r.follow(__moba.game,true);const s=r.camera.worldToScreen({x,y}),b=r.canvas.getBoundingClientRect();return {x:s.x+b.left,y:s.y+b.top};}',[x,y]);page.mouse.move(pos['x'],pos['y'])
    def click(x,y):
        aim(x,y);page.mouse.down();page.mouse.up()
    fixture();aim(44,20);page.mouse.down();page.wait_for_function('__moba.game.player.state.hohenCharge?.progress>=1.5')
    assert page.evaluate('__target.hp===100000&&__moba.game.player.ammo===0')
    expect(page.locator('#champion-live-status')).to_contain_text('충전 100%')
    page.screenshot(path=str(art/'v20-hohenheim-full-charge.png'))
    page.mouse.up();page.wait_for_function('__hits.length===3');assert page.evaluate('__hits.every(h=>h.n===150)')
    page.wait_for_function('__moba.game.player.attackCd===0');page.evaluate('window.__hits=[]');click(44,20)
    page.wait_for_function('__hits.length===1');assert page.evaluate('__hits[0].n>=100&&__hits[0].n<110')
    page.wait_for_function('__moba.game.player.attackCd===0');aim(44,20);page.mouse.down();page.wait_for_function('__moba.game.player.state.hohenCharge')
    page.keyboard.press('Escape');page.mouse.up();assert page.evaluate('!__moba.game.player.state.hohenCharge&&__hits.length===1')
    expect(page.locator('#pause-banner')).to_be_hidden()
    fixture();page.evaluate('''() => {const g=__moba.game;g.deal(__target,g.player,1e6,{fixed:true});}''');aim(44,20);page.mouse.down()
    page.wait_for_function('__hits.length>=9');page.mouse.up()
    assert page.evaluate('__hits.every(h=>h.n===150)&&!__moba.game.player.state.hohenCharge')
    starts=page.evaluate('Array.from(new Set(__hits.map(h=>h.serial))).map(i=>__hits.find(h=>h.serial===i).at)')
    assert all(starts[i]-starts[i-1]>=.65-1e-6 for i in range(1,len(starts)))
    page.screenshot(path=str(art/'v20-hohenheim-posthumous-bursts.png'))
    fixture();aim(44,20);page.locator('#arena').focus();page.keyboard.press('Space');assert page.evaluate('__moba.game.targeting?.slot')=='r'
    click(44,20);page.wait_for_function('__moba.game.zones.some(z=>z.kind==="electricDevice")')
    expect(page.locator('#r-btn span')).to_have_text('추적 대상 변경')
    page.evaluate('''() => {const g=__moba.game,z=g.zones[0],t=g.makeChampion('faust',1,8);Object.assign(t,{x:44,y:23,maxHp:100000,hp:100000,lastAttackAt:100,lastDamageAt:100});window.__next=t;window.__until=z.until;window.__originalCd=g.player.rCd;}''')
    aim(44,23);page.locator('#arena').focus();page.keyboard.press('Space');assert page.evaluate('__moba.game.targeting?.slot')=='r';click(44,23)
    page.wait_for_function('__moba.game.zones[0]?.manualTargetId===__next.id')
    assert page.evaluate('__moba.game.zones[0].until===__until&&__moba.game.player.rCd<=__originalCd')
    page.wait_for_timeout(250);page.screenshot(path=str(art/'v20-hohenheim-retarget-field.png'))
    page.evaluate('__moba.game.time=__until+.01');page.wait_for_function('__moba.game.zones.length===0')
    expect(page.locator('#r-btn span')).to_have_text('초고압 전류 방전')
    page.select_option('#training-champion','ahab');page.click('#training-change-champion');fixture()
    page.evaluate('''() => {const g=__moba.game,p=g.player,a=g.makeChampion('faust',0,9);Object.assign(a,{x:47.5,y:20,hp:100000,maxHp:100000});window.__ally=a;__target.state.harpoon={source:p.id,team:0,until:g.time+10};const hp=__target.hp;g.deal(a,__target,100,{fixed:true,proc:false});window.__cover=hp-__target.hp;}''')
    assert page.evaluate('__cover===130')
    aim(44,20);page.mouse.down(button='right');page.mouse.up(button='right');page.wait_for_function('__moba.game.player.state.order==="guard"')
    assert page.evaluate('''() => {const g=__moba.game,p=g.player,h=p.hp,a=__ally.hp;g.deal(__target,p,100,{fixed:true});return Math.abs(h-p.hp-70)<1e-6&&Math.abs(a-__ally.hp-30)<1e-6;}''')
    page.screenshot(path=str(art/'v20-ahab-eight-radius-orders.png'))
    page.click('#pause');page.click('#leave');page.click('#archive-open');page.fill('#roster-search','호엔하임');page.click('#roster-list button')
    expect(page.locator('#roster-detail')).to_contain_text('탄창 없음')
    expect(page.locator('#roster-detail')).to_contain_text('150 피해')
    expect(page.locator('#roster-detail')).to_contain_text('0.65초')
    page.click('#archive .close-dialog')
    page.set_viewport_size({'width':390,'height':844});page.click('#start');page.wait_for_timeout(150)
    assert page.evaluate('document.body.scrollWidth<=innerWidth')
    assert not errors,errors;b.close()
    print(json.dumps({'status':'passed','checks':['real hold/release and charge HUD','tap and 0.65-second posthumous bursts','Escape cancellation','coordinate ultimate and manual target change','seven-second expiration and cooldown preservation','Ahab eight-radius cover/guard','codex and mobile layout'],'page_errors':errors},ensure_ascii=False))
